def find_tuple_intersection(list1, list2):
    # 將元組內的元素排序，並轉為 frozenset 以確保順序不影響比較
    set1 = {frozenset(t) for t in list1}
    set2 = {frozenset(t) for t in list2}

    # 取交集並轉回 tuple 格式
    intersection = [tuple(sorted(list(s))) for s in set1.intersection(set2)]
    return set(intersection)

